VALUES ('theme_2', '마음 테라피', '편안한 심신과 평온을 되찾아 드립니다.', '불안하고 긴장된 마음을 위한 맞춤형 사운드입니다. 고요하고 조화로운 소리가 심리적 안정감을 경험하도록 돕습니다.', ARRAY['S002','S004','S005','S006','S008','S013','S015','S017','S018','S019','S022'], ARRAY['지쳤어요'], 2);
INSERT INTO themes (id, title, subtitle, description, track_ids, moods, display_order) 
VALUES ('theme_3', '이명 케어(자연소리)', '이명 소리를 케어해주는 편안한 자연의 소리를 만나보세요.', '이명을 효과적으로 마스킹할 수 있도록 설계한 백색소음 입니다. 평온하고 안정적인 상태를 돕습니다.', ARRAY['S031','S032','S033','S034','S035','S036'], ARRAY['귀에서 소리가 나요'], 3);
INSERT INTO themes (id, title, subtitle, description, track_ids, moods, display_order) 
VALUES ('theme_4', '활력 부스터', '지친 하루에 새로운 활력을 채워보세요.', '활기찬 에너지를 채우는 100BPM이상의 리듬을 고려하여 더욱 경쾌하고 긍정적인 분위기를 만들어줍니다. ', ARRAY['S003','S004','S020','S024','S025','S028'], ARRAY['기운이 없어요'], 4);
INSERT INTO themes (id, title, subtitle, description, track_ids, moods, display_order) 
VALUES ('theme_5', '자연의 음악', '아름다운 음악에 자연의 소리를 더해 풍요로운 일상을 선사합니다.', '시원한 파도, 편안한 빗소리, 자연의 소리와 음악을 함께 설계하였습니다. 즉각적인 안정 효과를 느껴보세요.', ARRAY['S008','S009','S011','S012','S021','S023'], ARRAY['조용히 쉬고싶어요'], 5);
INSERT INTO themes (id, title, subtitle, description, track_ids, moods, display_order) 
VALUES ('theme_6', '일상의 낭만', '커피 한 잔, 즐거운 식사, 산책 등 특별한 감성을 더해드립니다.', '감각적인 재즈, 낭만적인 클래식을 더하여 공간에 맞는 음악을 더해보세요.', ARRAY['S003','S026','S027','S028','S029','S031'], ARRAY['기분 전환하고 싶어요'], 6);
